    if evtype in ('cross-referenced', 'referenced'):
        src = e.get('source', {})
        if 'issue' in src:
            print(f'Event: {evtype} -> #{src[\"issue\"][\"number\"]} \"{src[\"issue\"][\"title\"]}\" by {src[\"issue\"][\"user\"][\"login\"]} (state: {src[\"issue\"][\"state\"]})')
    elif evtype in ('closed', 'labeled'):
        actor = e.get('actor', {}).get('login', '?')
        label = e.get('label', {}).get('name', '')
        print(f'Event: {evtype} by {actor} {label} at {e.get(\"created_at\",\"?\")}')
" 2>&1', 'description': 'Check cross-references and events on the issue'}
